#!/usr/bin/env python3
import hashlib, html, json, runpy, time
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260829_1000.py')),run_name='recipe_base')
TITLE='Bolinho de Lentilha Assado para Bebê: Receita Macia com Legumes'; SLUG_KEY='bolinho-lentilha-assado-bebe'; CLUSTER='Cluster 5 — Refeições com feijão, lentilha, grão-de-bico e outras leguminosas'; KEYWORD='bolinho de lentilha assado para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']
def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Bolinho assado de lentilha com cenoura e aveia, com textura macia e formato adaptável às habilidades da criança.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, lentilha, legumes','recipeYield':'8 bolinhos pequenos','recipeIngredient':['1 xícara de lentilha cozida e bem escorrida','2 colheres (sopa) de cenoura ralada fina','2 colheres (sopa) de aveia em flocos finos','1 colher (sopa) de cebola bem picada'],'recipeInstructions':[{'@type':'HowToStep','text':'Amasse a lentilha cozida com o garfo, deixando alguma textura.'},{'@type':'HowToStep','text':'Misture cenoura, aveia e cebola até obter massa úmida que mantenha o formato.'},{'@type':'HowToStep','text':'Modele bolinhos achatados e asse a 200 °C até firmarem, sem deixar ressecar.'},{'@type':'HowToStep','text':'Espere amornar e adapte tamanho e formato às habilidades da criança.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Este bolinho de lentilha assado combina lentilha cozida, cenoura e aveia em uma preparação simples, úmida por dentro e fácil de adaptar. É uma maneira diferente de levar uma leguminosa à refeição sem transformar tudo em creme ou purê.</p><p><strong>Atenção:</strong> adapte tamanho, formato e textura às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação ou deglutição e necessidades especiais exigem avaliação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>1 xícara de lentilha cozida e bem escorrida</li><li>2 colheres (sopa) de cenoura ralada fina</li><li>2 colheres (sopa) de aveia em flocos finos</li><li>1 colher (sopa) de cebola bem picada</li></ul><h2>Modo de preparo</h2><ol><li>Preaqueça o forno a 200 °C.</li><li>Amasse a lentilha já cozida com um garfo. Não é necessário transformar em pasta totalmente lisa.</li><li>Junte a cenoura, a aveia e a cebola. Misture até formar uma massa úmida que consiga manter o formato.</li><li>Modele bolinhos pequenos e levemente achatados, sem compactar demais, e disponha em assadeira.</li><li>Asse até ficarem firmes o suficiente para segurar, mas ainda macios por dentro. Evite prolongar o forno até formar uma crosta dura.</li><li>Espere amornar antes de servir.</li></ol><h2>Como deve ficar a textura</h2><p>O interior deve ceder facilmente quando pressionado com o garfo. Se a mistura estiver quebradiça antes de assar, amasse um pouco mais a lentilha; se estiver excessivamente úmida, acrescente aveia aos poucos.</p><h2>Como servir e adaptar</h2><p>O formato deve acompanhar as habilidades da criança. O bolinho pode ser oferecido inteiro quando o formato for adequado para pegar com as mãos ou desmanchado com o garfo para uma textura mais fácil de manejar. O Ministério da Saúde orienta que, a partir dos 6 meses, alimentos in natura ou minimamente processados sejam incluídos e que a consistência evolua gradualmente.</p><h2>Por que usar lentilha nesta receita?</h2><p>A lentilha faz parte do grupo dos feijões e outras leguminosas citado pelo Guia Alimentar para Crianças Brasileiras Menores de 2 Anos. Aqui ela aparece em uma textura assada diferente das preparações de colher, ampliando as possibilidades culinárias sem atribuir benefícios médicos ao ingrediente.</p><h2>Substituições culinárias</h2><p>A cenoura pode ser trocada por abobrinha ralada e bem espremida, lembrando que a umidade da massa pode mudar. A aveia deve ser ajustada apenas o suficiente para modelar. Para alergias ou necessidades alimentares específicas, procure profissional habilitado em vez de fazer substituições por conta própria.</p><h2>Armazenamento</h2><p>Use utensílios limpos e lentilha recém-cozida ou corretamente refrigerada. Não guarde novamente a porção que já teve contato com a boca ou com utensílio usado durante a refeição. Para conservar sobras, siga orientações oficiais de higiene, refrigeração e reaquecimento compatíveis com as condições disponíveis em casa.</p><h2>Perguntas frequentes</h2><h3>Precisa usar ovo para dar liga?</h3><p>Não nesta versão. A lentilha amassada e a aveia ajudam a manter o formato. A quantidade de aveia pode variar um pouco conforme a umidade da lentilha.</p><h3>Posso bater a lentilha no liquidificador?</h3><p>Não é necessário. Amassar com o garfo permite controlar melhor a consistência e preservar uma textura macia sem deixar a massa líquida.</p><h3>O bolinho deve ficar crocante?</h3><p>Não. Para esta proposta, o objetivo é um bolinho firme o bastante para manter o formato e macio por dentro, sem casca rígida.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/creme-de-lentilha-com-legumes-para-bebe.html'>Creme de Lentilha com Legumes para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/palitinhos-de-legumes-assados-para-bebe.html'>Palitinhos de Legumes Assados para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/bolinho-de-batata-doce-e-frango-assado.html'>Bolinho de Batata-Doce e Frango Assado para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-brasil/eu-quero-me-alimentar-melhor/Documentos/pdf/guia-alimentar-para-criancas-brasileiras-menores-de-2-anos.pdf/' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>O bolinho de lentilha assado oferece uma textura diferente para a leguminosa e pode ser ajustado conforme as habilidades da criança, mantendo uma preparação caseira simples e sem depender de produtos prontos.</p><script type='application/ld+json'>{sj}</script>"""
def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('bolinho' in t and 'lentilha' in t and 'assad' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for lentil patties'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists():
  original=base['TITLE']; base['TITLE']=TITLE
  try: base['generate_cover'](cp)
  finally: base['TITLE']=original
  base['git_commit_push']([cp],'Add unique AI food photo for baked lentil patties'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Almoço','Jantar','Lentilha','Leguminosas']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published baked lentil patty recipe')
if __name__=='__main__': main()
